require __DIR__.'/auth.php';require __DIR__.'/config.php';$payload=file_get_contents('php://input');$sig=$_SERVER['HTTP_STRIPE_SIGNATURE']??'';function valid_sig($p,$s,$secret){$ts=null;$v=[];foreach(explode(',',$s) as $x){[$k,$val]=array_pad(explode('=',$x,2),2,'');if($k==='t')$ts=$val;if($k==='v1')$v[]=$val;}if(!$ts||abs(time()-(int)$ts)>300)return false;$exp=hash_hmac('sha256',$ts.'.'.$p,$secret);foreach($v as $x)if(hash_equals($exp,$x))return true;return false;}if(!valid_sig($payload,$sig,$STRIPE_WEBHOOK_SECRET)){http_response_code(400);exit('Invalid signature');}$e=json_decode($payload,true);if(($e['type']??'')==='checkout.session.completed'){$x=$e['data']['object'];if(($x['payment_status']??'')!=='paid')exit('Not paid');$inv=$x['metadata']['invoice_id']??'';$uid=(int)($x['metadata']['user_id']??0);$scans=(int)($x['metadata']['scans']??0);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM payments WHERE invoice_id=? AND user_id=? FOR UPDATE');$q->execute([$inv,$uid]);$p=$q->fetch();if(!$p)throw new Exception('Order not found');if($p['status']!=='paid'){if((float)$p['amount']!==round(((int)$x['amount_total'])/100,2)||$p['scans']!=$scans)throw new Exception('Payment mismatch');$q=$pdo->prepare("UPDATE payments SET status='paid',trx_id=?,paid_at=NOW() WHERE id=?");$q->execute([$x['id'],$p['id']]);$q=$pdo->prepare('UPDATE users SET credits=credits+? WHERE id=?');$q->execute([$scans,$uid]);}$pdo->commit();}catch(Throwable $ex){$pdo->rollBack();http_response_code(400);exit($ex->getMessage());}}header('Content-Type: application/json');echo json_encode(['ok'=>true]);
